    if n == 0:
        return "zero"
    return "positive"


def summarize(rows, strict=False):
    total = 0
    for row in rows:
        if row is None:
            continue
        if strict and row < 0:
            raise ValueError("negative row")
        if row > 100 or row < -100:
            total += 100
        else:
            total += row
    return total

